-- Table Structure for: employee_requests
CREATE TABLE IF NOT EXISTS public."employee_requests" (
  "id" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  "employee_name" TEXT,
  "reason" TEXT DEFAULT ,
  "request_date" TIMESTAMPTZ DEFAULT now(),
  "status" TEXT DEFAULT 'Pending'
);

-- Table Structure for: employees
CREATE TABLE IF NOT EXISTS public."employees" (
  "id" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  "name" TEXT,
  "contact_number" TEXT DEFAULT ,
  "address" TEXT DEFAULT ,
  "gender" TEXT DEFAULT 'Male',
  "age" INTEGER DEFAULT 0,
  "blood_type" TEXT DEFAULT ,
  "allergies" TEXT DEFAULT ,
  "pre_existing_conditions" TEXT DEFAULT ,
  "emergency_contact" TEXT DEFAULT 
);

-- Data for: employees

-- Table Structure for: medicine_batches
CREATE TABLE IF NOT EXISTS public."medicine_batches" (
  "id" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  "scientific_name" TEXT,
  "brand" TEXT,
  "milligrams" INTEGER,
  "added_date" TIMESTAMPTZ DEFAULT now(),
  "expiry_date" TIMESTAMPTZ,
  "illness" TEXT DEFAULT ,
  "quantity" INTEGER DEFAULT 0
);

-- Data for: medicine_batches

-- Table Structure for: medical_records
CREATE TABLE IF NOT EXISTS public."medical_records" (
  "id" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  "employee_name" TEXT,
  "date" TIMESTAMPTZ DEFAULT now(),
  "temperature" NUMERIC DEFAULT 36.5,
  "systolic" INTEGER DEFAULT 120,
  "diastolic" INTEGER DEFAULT 80,
  "pulse_rate" TEXT DEFAULT ,
  "chief_complaint" TEXT DEFAULT ,
  "medicine_given" TEXT DEFAULT 'None',
  "management" TEXT,
  "remarks" TEXT
);

-- Data for: medical_records

-- Table Structure for: request_items
CREATE TABLE IF NOT EXISTS public."request_items" (
  "id" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  "request_id" UUID,
  "medicine_name" TEXT,
  "quantity" INTEGER DEFAULT 1
);

-- Table Structure for: disposed_medicines
CREATE TABLE IF NOT EXISTS public."disposed_medicines" (
  "id" UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  "scientific_name" TEXT,
  "brand" TEXT,
  "milligrams" INTEGER,
  "quantity" INTEGER,
  "added_date" TIMESTAMPTZ,
  "expiry_date" TIMESTAMPTZ,
  "disposed_date" TIMESTAMPTZ DEFAULT now()
);

